import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  nativeSelectDescriptionClassName,
  nativeSelectLabelClassName,
  nativeSelectRootClassName,
  nativeSelectTriggerClassName,
} from "./view";

export {
  nativeSelectDescriptionClassName,
  nativeSelectLabelClassName,
  nativeSelectRootClassName,
  nativeSelectTriggerClassName,
} from "./view";

export type OptionConfig = Readonly<{
  value: string;
  label: string;
  disabled?: boolean | undefined;
}>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
}>;

export type LabelViewConfig = Readonly<{
  forId: string;
  children: readonly Html[];
  className?: string | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  id: string;
  value: string;
  onChange: (value: string) => ParentMessage;
  options: readonly OptionConfig[];
  ariaLabel?: string | undefined;
  describedById?: string | undefined;
  disabled?: boolean | undefined;
  className?: string | undefined;
}>;

export type DescriptionViewConfig = Readonly<{
  id: string;
  children: readonly Html[];
  className?: string | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  className,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "native-select"),
      h.Class(classNames(nativeSelectRootClassName, className)),
    ],
    children
  );
};

export const labelView = <ParentMessage>({
  forId,
  children,
  className,
}: LabelViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.label(
    [
      h.For(forId),
      h.DataAttribute("slot", "native-select-label"),
      h.Class(classNames(nativeSelectLabelClassName, className)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  id,
  value,
  onChange,
  options,
  ariaLabel,
  describedById,
  disabled = false,
  className,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.select(
    [
      h.Id(id),
      h.Value(value),
      h.Disabled(disabled),
      h.OnChange(onChange),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(describedById === undefined
        ? []
        : [h.AriaDescribedBy(describedById)]),
      h.DataAttribute("slot", "native-select-trigger"),
      h.Class(classNames(nativeSelectTriggerClassName, className)),
    ],
    options.map((option) =>
      h.option(
        [
          h.Value(option.value),
          ...(option.disabled === true ? [h.Disabled(true)] : []),
        ],
        [option.label]
      )
    )
  );
};

export const descriptionView = <ParentMessage>({
  id,
  children,
  className,
}: DescriptionViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [
      h.Id(id),
      h.DataAttribute("slot", "native-select-description"),
      h.Class(classNames(nativeSelectDescriptionClassName, className)),
    ],
    children
  );
};

export const nativeSelectRootClassName = "grid w-full max-w-sm gap-2";
export const nativeSelectLabelClassName = "text-sm font-medium text-gray-950";
export const nativeSelectTriggerClassName =
  "h-10 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm text-gray-950 shadow-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 disabled:cursor-not-allowed disabled:opacity-50";
export const nativeSelectDescriptionClassName = "text-sm text-gray-600";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as NativeSelect from "./index";

const options = [
  { value: "apple", label: "Apple" },
  { value: "banana", label: "Banana" },
] as const;

const view = (value: string): Html => {
  const h = html<string>();

  return NativeSelect.rootView<string>({
    children: [
      NativeSelect.labelView<string>({
        forId: "fruit",
        children: [h.span([], ["Fruit"])],
      }),
      NativeSelect.triggerView<string>({
        id: "fruit",
        value,
        onChange: (nextValue) => nextValue,
        options,
        describedById: "fruit-description",
      }),
      NativeSelect.descriptionView<string>({
        id: "fruit-description",
        children: [h.span([], ["Choose a fruit"])],
      }),
    ],
  });
};

describe("Native Select registry view", () => {
  test("renders labelled native select and updates value", () => {
    Scene.scene(
      {
        update: (_model: string, message: string): readonly [string, []] => [
          message,
          [],
        ],
        view,
      },
      Scene.with("apple"),
      Scene.expect(Scene.role("combobox", { name: "Fruit" })).toHaveValue(
        "apple"
      ),
      Scene.change(Scene.role("combobox", { name: "Fruit" }), "banana"),
      Scene.expect(Scene.role("combobox", { name: "Fruit" })).toHaveValue(
        "banana"
      )
    );
  });
});
